13134   /// Emits actual operation for the scalar identity values, found during
13135   /// horizontal reduction analysis.
13136   Value *emitReusedOps(Value *VectorizedValue, IRBuilderBase &Builder,
13137                        ArrayRef<Value *> VL,
13138                        const MapVector<Value *, unsigned> &SameValuesCounter,
13139                        const DenseMap<Value *, Value *> &TrackedToOrig) {
13140     assert(IsSupportedHorRdxIdentityOp &&
13141            "The optimization of matched scalar identity horizontal reductions "
13142            "must be supported.");
13143     switch (RdxKind) {
13144     case RecurKind::Add: {
13145       // root = mul prev_root, <1, 1, n, 1>
13146       SmallVector<Constant *> Vals;
13147       for (Value *V : VL) {
13148         unsigned Cnt = SameValuesCounter.lookup(TrackedToOrig.find(V)->second);
13149         Vals.push_back(ConstantInt::get(V->getType(), Cnt, /*IsSigned=*/false));
13150       }
13151       auto *Scale = ConstantVector::get(Vals);
13152       LLVM_DEBUG(dbgs() << "SLP: Add (to-mul) " << Scale << "of "
13153                         << VectorizedValue << ". (HorRdx)\n");
13154       return Builder.CreateMul(VectorizedValue, Scale);
13155     }
13156     case RecurKind::And:
13157     case RecurKind::Or:
13158       // No need for multiple or/and(s).
13159       LLVM_DEBUG(dbgs() << "SLP: And/or of same " << VectorizedValue
13160                         << ". (HorRdx)\n");
13161       return VectorizedValue;
13162     case RecurKind::SMax:
13163     case RecurKind::SMin:
13164     case RecurKind::UMax:
13165     case RecurKind::UMin:
13166     case RecurKind::FMax:
13167     case RecurKind::FMin:
13168       // No need for multiple min/max(s) of the same value.
13169       LLVM_DEBUG(dbgs() << "SLP: Max/min of same " << VectorizedValue
13170                         << ". (HorRdx)\n");
13171       return VectorizedValue;
13172     case RecurKind::Xor: {
13173       // Replace values with even number of repeats with 0, since
13174       // x xor x = 0.
13175       // root = shuffle prev_root, zeroinitalizer, <0, 1, 2, vf, 4, vf, 5, 6,
13176       // 7>, if elements 4th and 6th elements have even number of repeats.
13177       SmallVector<int> Mask(
13178           cast<FixedVectorType>(VectorizedValue->getType())->getNumElements(),
13179           UndefMaskElem);
13180       std::iota(Mask.begin(), Mask.end(), 0);
13181       bool NeedShuffle = false;
13182       for (unsigned I = 0, VF = VL.size(); I < VF; ++I) {
13183         Value *V = VL[I];
13184         unsigned Cnt = SameValuesCounter.lookup(TrackedToOrig.find(V)->second);
13185         if (Cnt % 2 == 0) {
13186           Mask[I] = VF;
13187           NeedShuffle = true;
13188         }
13189       }
13190       LLVM_DEBUG(dbgs() << "SLP: Xor <"; for (int I
13191                                               : Mask) dbgs()
13192                                          << I << " ";
13193                  dbgs() << "> of " << VectorizedValue << ". (HorRdx)\n");
13194       if (NeedShuffle)
13195         VectorizedValue = Builder.CreateShuffleVector(
13196             VectorizedValue,
13197             ConstantVector::getNullValue(VectorizedValue->getType()), Mask);
13198       return VectorizedValue;
13199     }
13200     case RecurKind::FAdd: {
13201       // root = fmul prev_root, <1.0, 1.0, n.0, 1.0>
13202       SmallVector<Constant *> Vals;
13203       for (Value *V : VL) {
13204         unsigned Cnt = SameValuesCounter.lookup(TrackedToOrig.find(V)->second);
13205         Vals.push_back(ConstantFP::get(V->getType(), Cnt));
13206       }
13207       auto *Scale = ConstantVector::get(Vals);
13208       return Builder.CreateFMul(VectorizedValue, Scale);
13209     }
13210     case RecurKind::Mul:
13211     case RecurKind::FMul:
13212     case RecurKind::FMulAdd:
13213     case RecurKind::SelectICmp:
13214     case RecurKind::SelectFCmp:
13215     case RecurKind::None:
13216       llvm_unreachable("Unexpected reduction kind for reused scalars.");
13217     }
13218     return nullptr;
13219   }
